in vec2 FragCoord;
uniform float uTime;
vec2 perlin_noise_dir(vec2 p) {
	p = mod(p, 289.0);

	float x = mod((34.0 * p.x + 1.0) * p.x, 289.0) + p.y;

	x = mod((34.0 * x + 1.0) * x, 289.0);

	x = fract(x / 41.0) * 2.0 - 1.0;

	return normalize(vec2(x - floor(x + 0.5), abs(x) - 0.5));
}

float perlin_noise(vec2 p) {
	vec2 ip = floor(p);
	vec2 fp = fract(p);
	float d00 = dot(perlin_noise_dir(ip), fp);
	float d01 = dot(perlin_noise_dir(ip + vec2(0, 1)), fp - vec2(0, 1));
	float d10 = dot(perlin_noise_dir(ip + vec2(1, 0)), fp - vec2(1, 0));
	float d11 = dot(perlin_noise_dir(ip + vec2(1, 1)), fp - vec2(1, 1));
	fp = fp * fp * fp * (fp * (fp * 6.0 - 15.0) + 10.0);

	return mix(mix(d00, d01, fp.y), mix(d10, d11, fp.y), fp.x);
}

void generate_perlin_noise_float(vec2 uv, float scale, out float out_buffer) {
	out_buffer = perlin_noise(uv * scale) + 0.5;
}

out vec4 FragColor;

void main() {
// Input:1
	vec2 var_from_n1_p0 = FragCoord;


// PerlinNoise:3
	// Perlin Noise
	float out_buffer_n3 = 0.0;
	generate_perlin_noise_float(var_from_n1_p0, 50.000000, out_buffer_n3);
	vec4 var_from_n3_p0 = vec4(out_buffer_n3, out_buffer_n3, out_buffer_n3, 1.0);



// Input:2
	float var_from_n2_p0 = uTime;


// FloatFunc:4
	float var_from_n4_p0 = sin(var_from_n2_p0);


// FloatConstant:5
	float var_from_n5_p0 = 2.000000;


// FloatOp:6
	float var_from_n6_p0 = var_from_n4_p0 / var_from_n5_p0;


// FloatOp:7
	float var_from_n7_p0 = var_from_n3_p0.x - var_from_n6_p0;


// FloatFunc:8
	float var_from_n8_p0 = round(var_from_n7_p0);


// Output:0
	FragColor = vec4(var_from_n8_p0);


}
